code_sketch:
enum Shape { Circle(f64), Square(f64) }

fn collide(a: &Shape, b: &Shape) -> String {
    match (a, b) {
        (Shape::Circle(r), Shape::Square(s)) => format!("circle {r} vs square {s}"),
        (Shape::Square(s), Shape::Circle(r)) => collide(b, a),   // canonicalise symmetric pairs
        (Shape::Circle(_), Shape::Circle(_)) => "two circles".into(),
        (Shape::Square(_), Shape::Square(_)) => "two squares".into(),
    }
}

variants.code_sketch:
enum Shape { Circle(f64), Square(f64) }

fn collide(a: &Shape, b: &Shape) -> String {
    match (a, b) {
        (Shape::Circle(r), Shape::Square(s)) => format!("circle {r} vs square {s}"),
        (Shape::Square(s), Shape::Circle(r)) => collide(b, a),   // canonicalise symmetric pairs
        (Shape::Circle(_), Shape::Circle(_)) => "two circles".into(),
        (Shape::Square(_), Shape::Square(_)) => "two squares".into(),
    }
}

trait Visitor {
    fn visit_circle(&mut self, c: &Circle);
    fn visit_square(&mut self, s: &Square);
}
trait Shape { fn accept(&self, v: &mut dyn Visitor); }

impl Shape for Circle {
    fn accept(&self, v: &mut dyn Visitor) { v.visit_circle(self); }   // dispatch #2 target
}
